/**
 * Determines if it is possible to travel from the start position to the end position in an n-interesting space.
 * 
 * @param n the size of the n-interesting space
 * @param start the starting position (row, column)
 * @param end the ending position (row, column)
 * @param paths the paths between adjacent positions
 * @return "can be travelled" if travel is possible, otherwise "cannot be travelled"
 */
public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    visited[start[0]][start[1]] = true;

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int row = current[0];
        int col = current[1];

        if (row == end[0] && col == end[1]) {
            return "can be travelled";
        }

        // Check left, right, top, bottom
        if (row > 0 && !visited[row - 1][col]) {
            visited[row - 1][col] = true;
            queue.offer(new int[]{row - 1, col});
        }
        if (row < n - 1 && !visited[row + 1][col]) {
            visited[row + 1][col] = true;
            queue.offer(new int[]{row + 1, col});
        }
        if (col > 0 && !visited[row][col - 1]) {
            visited[row][col - 1] = true;
            queue.offer(new int[]{row, col - 1});
        }
        if (col < n - 1 && !visited[row][col + 1]) {
            visited[row][col + 1] = true;
            queue.offer(new int[]{row, col + 1});
        }
    }

    return "cannot be travelled";
}
