    public String sortString(String s) {
        PriorityQueue<Character> minHeap = new PriorityQueue<>();
        PriorityQueue<Character> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());
        StringBuilder result = new StringBuilder();

        // Populate the heaps with characters from the string
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                minHeap.offer(c);
            } else {
                maxHeap.offer(c);
            }
        }

        // Continue until we have processed all characters in the string
        while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
            if (!minHeap.isEmpty()) {
                result.append(minHeap.poll());
                // Ensure we don't use the same character twice in the result unless it appears more than once
                while (!minHeap.isEmpty() && minHeap.peek() == result.charAt(result.length() - 1)) {
                    minHeap.poll();
                }
