public class Solution {
    public int maxUniqueSplit(String s) {
        return maxUniqueSplit(s, new HashSet<>());
    }

    private int maxUniqueSplit(String s, Set<String> used) {
        if (s.isEmpty()) {
            return 0;
        }

        int max = 0;
        for (int i = 1; i <= s.length(); i++) {
            String curr = s.substring(0, i);
            if (!used.contains(curr)) {
                used.add(curr);
                max = Math.max(max, 1 + maxUniqueSplit(s.substring(i), used));
                used.remove(curr);
            }
        }

        return max;
    }
}
