    int maxLength = 0;
    backtrack(s, 0, current, maxLength);
    return maxLength;
}

private void backtrack(String s, int start, List<String> current, int maxLength) {
    if (start == s.length()) {
        maxLength = Math.max(maxLength, current.size());
        return;
    }

    for (int i = start; i < s.length(); i++) {
        String substring = s.substring(start, i + 1);
        if (current.contains(substring)) continue;
        current.add(substring);
        backtrack(s, i + 1, current, maxLength);
        current.remove(current.size() - 1);
    }
}
