private static void findSteppingNumbersInternal(List<Integer> numbers, int low, int high, int currentNumber) {
    if (currentNumber == 0 || currentNumber < low || currentNumber > high) {
        return;
    }
    if (currentNumber >= low && currentNumber <= high) {
        numbers.add(currentNumber);
    }
    int next = currentNumber * 10;
    if (next >= low && next <= high) {
        numbers.add(next + 1);
        if (next >= low && next <= high)
            numbers.add(next - 1);
        if (next >= low && next <= high)
            numbers.add(next + 0);
        if (next >= low && next <= high)
            numbers.add(next - 0);
        if (next >= low && next <= high)
            numbers.add(next + 1);
        if (next >= low && next <= high)
            numbers.add(next - 1);
    }
    findSteppingNumbersInternal(numbers, low, high, next + 1);
    findSteppingNumbersInternal(numbers, low, high, next - 1);
    // Add 0 to the streak of increasing/decreasing by 1
    findSteppingNumbersInternal(numbers, low, high, next + 0);
    findSteppingNumbersInternal(numbers, low, high, next - 0);
