public static int squarePermutations(int[] A) {
    if (A == null || A.length == 1) {
        return 1; // An array with one element, or an empty array, has exactly one square permutation.
    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];

    // Base case: sorting the array gives all permutations
    int[] sortedA = A.clone();
    Arrays.sort(sortedA);

    // Check all permutations of the sorted array to see if they form a square array
    for (int i = 0; i < n; i++) {
        for (int bitmask = 1; bitmask < (1 << n); bitmask++) {
            boolean isValid = true;
            int j = 0;
            for (int index = 0; index < n; index++) {
                if ((bitmask & (1 << index)) != 0 && A[index] != sortedA[j]) {
                    isValid = false;
                    break;
                }
                j++;
            }
            if (isValid && isPerfectSquare(A[i] + sortedA[j])) {
                dp[i][bitmask] = 1 + dp[i - 1][bitmask ^ (1 << j)];
            } else {
                dp[i][bitmask] = dp[i - 1][bitmask];
            }
        }
    }

    // The result is the number of valid square permutations
    return dp[n - 1][(1 << n) - 1];
}

private static boolean isPerfectSquare(int num) {
    double sqrt = Math.sqrt(num);
    return sqrt == Math.floor(sqrt);
}
