public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(lastElement(mat));
    int[] result = new int[rows * cols];

    int index = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int[] current = queue.poll();
            result[index++] = current[0];

            if (current[0] == 0) {
                int right = rightMost(current);
                if (right != null) {
                    queue.offer(right);
                }
            } else if (current[0] == rows - 1) {
                int left = leftMost(current);
                if (left != null) {
                    queue.offer(left);
                }
            } else if (current[1] == 0) {
                int down = downMost(current);
                if (down != null) {
                    queue.offer(down);
                }
            } else {
                int up = upMost(current);
                if (up != null) {
                    queue.offer(up);
                }
            }
        }
    }

    return result;
}

private static int[] lastElement(int[][] mat) {
