public static int findSmallestInteger(int n) {
    if (n < 0) {
        return -1; // Negative numbers cannot be rearranged to form a new integer.
    }

    // Convert the integer to a list of digits.
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    // Sort the digits in ascending order.
    Collections.sort(digits);

    // Find the index of the first non-increasing element from the end.
    int index = digits.size() - 1;
    while (index > 0) {
        if (digits.get(index) > digits.get(index - 1)) {
            break;
        }
        --index;
    }

    // If all digits are in ascending order, no valid rearrangement exists.
    if (index == 0) {
        return -1;
    }

    // Find the smallest digit that is larger than the element at index.
    int right = index;
    while (right < digits.size() && digits.get(right) <= digits.get(index - 1)) {
        right++;
    }

    // Swap the two elements.
    Collections.swap(digits, index - 1, right);

    // Reverse the digits from the index to the end.
    Collections.reverse(digits, index);

    // Convert the list of digits back to an integer.
    int result = 0;
    for (int digit : digits) {
        result = result * 10 + digit;
    }

    return result;
}
