public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1; // There are no integers greater than 1 without rearrangement
    }

    int decreasingTail = -1, increasingHead = -1;
    for (int i = n; i > 0; i /= 10) {
        int digit = i % 10;
        if (digit > n % 10) {
            if (decreasingTail == -1) {
                decreasingTail = digit;
            } else {
                // Found a smaller digit to replace to get smaller integers
                return Integer.valueOf(digits(0, decreasingTail) + "1" + digits(decreasingTail + 1, digits.length()));
            }
        }
        if (digit < n % 10) {
            increasingHead = digit;
        }
    }

    if (decreasingTail == -1) {
        return -1; // No way to make a number smaller than n with rearrangement
    }

    // Replace the first occurrence of decreasingTail with increasingHead
    int[] digits = digits(n);
    int index = -1;
    for (int i = 0; i < digits.length; i++) {
        if (digits[i] == decreasingTail) {
            index = i;
            break;
        }
    }
    int temp = digits[index];
    digits[index] = digits[increasingHead];
    digits[increasingHead] = temp;

    return Integer.valueOf(digits.join(""));
}

private static char[] digits(int start, int end) {
    char[] arr = new char[end - start];
    int count = 0;
    for (int i = start; i < end; i++) {
        arr[count++] = (char) (i + '0');
    }
    return arr;
}
