import java.util.Stack;

/**
 * DP solution to find minimum number of perfect square numbers that sum up to a given integer.
 */
public class MinPerfectSquareSum {
    public static int minPerfectSquareSum(int n) {
        Stack<Integer> stack = new Stack<>();
        if (n <= 0) return 0;

        for (int i = 1; i <= n; i++) {
            stack.push(i);
        }

        while (!stack.isEmpty() && n > 0) {
            final int num = stack.pop();

            while (n - num > 0) {
                stack.push(n - num);
                n = n - num;
            }
        }

        return stack.size();
    }

    public static void main(String[] args) {
        System.out.println(minPerfectSquareSum(12)); // Output: 3
        System.out.println(minPerfectSquareSum(13)); // Output: 2
    }
}
